def post_migrate_roles(apps, schema_editor):
    Usuario = apps.get_model('accounts', 'Usuario')
    Rol = apps.get_model('accounts', 'Rol')
    db_alias = schema_editor.connection.alias

    dueno = Rol.objects.using(db_alias).filter(codigo='DUENO').first()
    admin = Rol.objects.using(db_alias).filter(codigo='ADMINISTRADOR').first()
    mecanico = Rol.objects.using(db_alias).filter(codigo='MECANICO').first()
    recep = Rol.objects.using(db_alias).filter(codigo='RECEPCIONISTA').first()

    for u in Usuario.objects.using(db_alias).all():
        uname = u.username.lower()
        if 'admin' in uname or uname == 'job':
            u.rol = dueno
        elif 'recep' in uname:
            u.rol = recep
        elif 'mecanico' in uname:
            u.rol = mecanico
        else:
            u.rol = admin or dueno
        u.save(update_fields=['rol'])


